import {VERSION,ASSET_VERSION,SKILL_NAMES,answerState,restoreRun,listeningGroups,STORAGE_KEY,PROFILES,profileOf,createRun,sectionQuestions,remaining,sync,setAnswer,navigate,nextGmat,advance,terminate,report,isCorrect} from './simulation.mjs?v=simulation20261027r2';
const root=document.querySelector('#main'),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let bank,run=null,error='',reviewFilter='all',audioBusy=false,utterance=null,playingGroup=null,audioEpoch=0,recovery=null,lastVisit=Date.now();
const fmt=n=>`${Math.floor(n/60).toString().padStart(2,'0')}:${(n%60).toString().padStart(2,'0')}`;
function save(){if(!run)return;try{localStorage.setItem(STORAGE_KEY,JSON.stringify(run));error='';}catch{error='此瀏覽器無法保存作答。請保持本頁開啟，完成後下載報告。';}const el=document.querySelector('#storage-error');if(el){el.textContent=error;el.hidden=!error;}}
function stopAudio(){audioEpoch++;if(audioBusy&&playingGroup&&run?.audio[playingGroup]==='started')run.audio[playingGroup]='error';globalThis.speechSynthesis?.cancel();utterance=null;audioBusy=false;playingGroup=null;}
function markTime(){if(run?.status==='active'){const q=sectionQuestions(run)[run.index];if(q)run.spent[q.id]=(run.spent[q.id]||0)+Math.max(0,Math.min(Date.now(),run.deadline)-lastVisit);}lastVisit=Date.now();}
function home(){return `<section class="intro"><p class="eyebrow">ENGLISH QUEST / PRACTICE UNDER EXAM CONDITIONS</p><h1>把時間，也一起練進去。</h1><p>選一份英文試卷，按照考試節次作答。開始後不暫停；離開頁面與重新整理仍繼續計時。答案與解析在整份交卷後開放。</p><p class="small">本站原創及既有練習整合為固定卷，非官方試題或正式成績預測。各卷的適性、錄音與內容差異在開始前列明。</p></section>${run?`<section class="panel resume"><h2>${esc(profileOf(run.profile)?.title)} · ${run.status==='active'?'進行中':'已完成'}</h2><p>${run.status==='active'?'原始倒數持續進行，接續不會重設時間。':'可以重新查看逐題解析與下載作答紀錄。'}</p><button class="primary" data-act="resume">${run.status==='active'?'回到考場':'查看報告'}</button>${run.status==='active'?'<button class="danger" data-act="terminate">提前終止模考</button>':''}</section>`:''}${recovery?'<section class="notice"><b>舊紀錄無法安全接續</b><p>請先下載原始備份，再開始新卷；備份保留原始作答資料。</p><button data-act="recovery-download">下載復原備份</button></section>':''}<div class="cards">${PROFILES.map(p=>`<article class="card"><p class="eyebrow">${p.id.toUpperCase()}</p><h2>${p.title}</h2><p><b>${p.scope}</b></p><p>${p.types}</p><button class="primary" data-act="prepare" data-id="${p.id}" ${run?.status==='active'?'disabled':''}>查看規則與開始</button></article>`).join('')}</div><p class="small">目前每種測驗各一份固定卷，重做會再次看到相同內容。學測／英檢寫作需人工評閱；英檢目前為中級，尚無初級、中高級與口說卷。</p><dialog id="setup"></dialog>`;}
function prepare(id){const p=profileOf(id),d=document.querySelector('#setup');d.innerHTML=`<h2>${p.title}</h2><ol>${p.sections.map(s=>`<li>${s.title}：${s.count} 個作答項目，${s.seconds/60} 分鐘。</li>`).join('')}</ol><div class="notice">${p.note}</div><p>不暫停、不即時公布答案。分節結束後不可返回前節。到時自動鎖定並開始下一節，離頁時間照計。</p>${p.sections.some(s=>s.listening)?'<p>請先測試音量。正式聽辨時依序播放一次，不提供逐字稿與重播；播放失敗會標記音訊中斷。可切換到全螢幕；瀏覽器無法執行官方監考限制。</p><button data-act="sound-check">▶ 測試英文語音</button><p id="sound-check-status" role="status"></p>':''}<p><a href="${p.source}" target="_blank" rel="noopener">核對官方題型與時間 ↗</a></p><p class="small">${run||recovery?'開始新卷會取代目前的本機紀錄，請先下載要保留的報告或復原備份。':'作答保存在此瀏覽器。'}</p><div class="row"><button class="primary" data-act="begin" data-id="${id}">開始正式計時</button><button data-act="close-dialog">返回</button></div>`;d.showModal();}
function choice(q,value){if(q.type==='writing')return `<label for="answer">英文作答</label><textarea id="answer" spellcheck="false" autocomplete="off" data-input="${q.id}">${esc(value||'')}</textarea><p id="word-count" class="small">${String(value||'').trim().split(/\s+/).filter(Boolean).length} words · 自動保存</p>`;
 if(q.type==='text')return `<label for="answer">輸入答案</label><input id="answer" type="text" spellcheck="false" autocomplete="off" value="${esc(value||'')}" data-input="${q.id}">`;
 if(q.type==='blanks')return q.blanks.map((opts,i)=>`<label>Blank ${i+1}<select data-blank="${i}" data-q="${q.id}"><option value="">選擇…</option>${opts.map(o=>`<option ${value?.[i]===o?'selected':''} value="${esc(o)}">${esc(o)}</option>`).join('')}</select></label>`).join('');
 return `${q.type==='multi'?`<p class="small">${q.selectCount?'請選 '+q.selectCount+' 個選項':'請選出所有符合的選項；可能超過一個'}</p>`:''}<div class="options">${q.options.map((o,i)=>`<button class="option ${Array.isArray(value)?value.includes(i)?'on':'':value===i?'on':''}" aria-pressed="${Array.isArray(value)?value.includes(i):value===i}" data-act="answer" data-value="${i}" ${run.profile==='gmat'&&run.review&&run.edits>=3&&value!==i?'disabled':''}><b>${String.fromCharCode(65+i)}</b><span lang="en">${esc(o)}</span></button>`).join('')}</div>`;}
function room(){const p=profileOf(run.profile),s=p.sections[run.section],qs=sectionQuestions(run),q=qs[run.index],value=run.answers[q.id];
 return `<div id="storage-error" class="storage-error" role="alert" ${error?'':'hidden'}>${esc(error)}</div><header class="room-head"><div><h1>${p.title}</h1><p>${s.title} · 第 ${run.index+1}／${qs.length} 題${run.review?' · 檢視改答':''}</p><p id="answer-progress" class="small">完整作答 ${qs.filter(x=>answerState(x,run.answers[x.id])==='complete').length}／${qs.length}</p></div><div><div id="clock" class="clock" role="timer" aria-label="本節剩餘時間">${fmt(remaining(run))}</div><span class="save-status">倒數不中斷 · 作答自動保存</span></div></header><div class="workspace"><section class="panel question"><div class="row"><span class="eyebrow">${esc(SKILL_NAMES[q.skill]||q.skill)}</span><button data-act="flag" aria-pressed="${!!run.flags[q.id]}">${run.flags[q.id]?'★ 已標記':'☆ 標記稍後檢查'}</button></div>${s.listening?`<p class="notice">聽力依序進行，每段只播一次。完成本題／題組後自動前進。</p><button class="primary" data-act="play" ${run.audio[q.group]?'disabled':''}>${run.audio[q.group]?'本段已播放':'▶ 播放本段音訊'}</button><p id="audio-status" class="audio-status small" role="status">${run.audio[q.group]==='error'?'本段音訊中斷，報告將註記。':run.audio[q.group]?'本段播放紀錄已保存。':'請確認音量；播放後才可作答。'}</p>`:''}${q.illustration?`<svg class="illustration" viewBox="0 0 250 180" role="img" aria-label="原創考題情境示意圖"><path d="${q.illustration}" fill="#687d77" stroke="#203d36" stroke-width="2"/></svg><p class="small">原創示意圖（非照片）</p>`:''}${q.passage&&!s.listening?`<div class="passage" lang="en">${esc(q.passage)}</div>`:''}<h2 lang="en" tabindex="-1">${esc(q.prompt)}</h2>${choice(q,value)}<div class="actions">${run.profile!=='gmat'&&(!s.listening||qs[run.index-1]?.group===q.group)?`<button data-act="previous" ${run.index===0?'disabled':''}>← 上一題</button>`:'<span></span>'}${run.profile==='gmat'&&!run.review?`<button class="primary" data-act="gmat-next" ${value===undefined?'disabled':''}>${run.index===qs.length-1?'進入檢視與改答':'確認答案並前進 →'}</button>`:(!s.listening||qs[run.index+1]?.group===q.group)?`<button data-act="next" ${run.index===qs.length-1?'disabled':''}>下一題 →</button>`:''}</div>${run.profile==='gmat'?`<p class="small">${run.review?'可檢視全部題目；剩餘改答次數 '+(3-run.edits)+'。每次更換選項計一次改答。':'前進後暫時不能返回，全部作答後才開放檢視及三次改答。'}</p>`:''}</section><aside class="panel navigator"><b>本節答題卡</b><p class="small">綠底：完整作答 · 黃底：部分作答 · 圓點：已標記</p><div class="numbers">${qs.map((x,i)=>`<button aria-label="第 ${i+1} 題${answerState(x,run.answers[x.id])==='complete'?'，完整作答':answerState(x,run.answers[x.id])==='partial'?'，部分作答':'，未作答'}" class="${answerState(x,run.answers[x.id])==='complete'?'answered':answerState(x,run.answers[x.id])==='partial'?'partial':''} ${run.index===i?'current':''} ${run.flags[x.id]?'flagged':''}" data-act="jump" data-index="${i}" ${s.listening||(run.profile==='gmat'&&!run.review)?'disabled':''}>${i+1}</button>`).join('')}</div><div class="row"><button data-act="fullscreen">全螢幕</button><button data-act="lobby">回入口</button><button class="danger" data-act="terminate">提前終止</button></div>${!s.listening&&(run.profile!=='gmat'||run.review)?'<button class="primary" data-act="finish-section">結束本節</button>':''}<p class="small">到時自動收卷。其他分節的答案無法在本節修改。</p></aside></div><dialog id="finish-dialog"></dialog>`;}
const answerLabel=(q,a)=>a===undefined||a===''?'未作答':q.type==='blanks'?a.map(v=>v||'未填').join(' / '):Array.isArray(a)?a.map(i=>q.options[i]).join(' ＋ '):typeof a==='number'?q.options[a]:a;
function results(){const p=profileOf(run.profile),r=report(run);return `<p class="eyebrow">EXAM COMPLETE / ${p.title}</p><h1>先看節奏，再看失分線索。</h1>${run.terminated?'<p class="notice">本次提前終止；未作答題目照實保留，不視為完成全卷。</p>':''}<div class="metrics"><div><div class="metric">${r.correct} / ${r.objective}</div>客觀題答對</div><div><div class="metric">${r.unanswered}</div>未完成${r.partial?'（部分作答 '+r.partial+'）':''}</div><div><div class="metric">${r.manual}</div>待人工評閱</div></div><p>作答紀錄：${new Date(run.startedAt).toLocaleString('zh-TW')} · 離頁 ${run.hiddenCount} 次 · 音訊中斷 ${Object.values(run.audio).filter(v=>v==='error').length} 段</p><div class="notice">這是本站固定練習卷的原始結果，不換算學測級分、英檢通過或 TOEIC／SAT／GRE／GMAT 正式分數。${p.note}</div><div class="row"><button class="primary" data-act="download">下載完整作答報告</button><button data-act="lobby">選擇其他考試</button><a class="button" href="./#exams">回到技能練習</a></div><h2>分節用時</h2><ul>${run.sectionResults.map((x,i)=>{const s=p.sections[i],start=i?run.sectionResults[i-1].endedAt:run.startedAt;return `<li>${s.title}：${fmt(Math.round((x.endedAt-start)/1000))}／${fmt(s.seconds)} · ${x.automatic?'時間到自動收卷':'自行交卷'}</li>`;}).join('')}</ul>${r.listening.total?`<section class="panel"><h2>聽力播放紀錄</h2><p>完整播放 ${r.listening.complete}／${r.listening.total} 段 · 中斷 ${r.listening.interrupted} · 未播 ${r.listening.missed}</p>${r.listening.complete<r.listening.total?'<p class="small">音訊未完整播放，本次答案不能單獨視為聽辨能力證據。</p>':''}</section>`:''}<h2>題型回饋</h2><table><thead><tr><th>題型</th><th>答對／題數</th></tr></thead><tbody>${r.skills.map(x=>`<tr><td>${esc(SKILL_NAMES[x.skill]||x.skill)}</td><td>${x.correct}／${x.total}</td></tr>`).join('')}</tbody></table><details class="panel"><summary>逐題答案、解析與寫作評閱要點（${r.total}）</summary><label>檢視範圍 <select id="review-filter"><option value="all">全部題目</option><option value="incorrect">需訂正</option><option value="incomplete">未完整作答</option><option value="flagged">已標記</option><option value="manual">待人工評閱</option></select></label><p id="review-count" class="small" role="status"></p>${run.questions.map((q,i)=>{const ok=isCorrect(q,run.answers[q.id]);return `<article class="review-item" data-correct="${ok===true}" data-manual="${ok===null}" data-incomplete="${answerState(q,run.answers[q.id])!=='complete'}" data-flagged="${!!run.flags[q.id]}"><h3>${i+1}. ${ok===null?'待評閱':ok?'✓ 答對':'需訂正'} · ${esc(SKILL_NAMES[q.skill]||q.skill)}</h3>${q.passage?`<div class="passage" lang="en">${esc(q.passage)}</div>`:''}${q.audio?`<p lang="en">${esc(q.audio)}${q.spokenOptions?' '+esc(q.spokenOptions.map((o,i)=>String.fromCharCode(65+i)+'. '+o).join(' ')):''}</p>`:''}<p lang="en"><b>${esc(q.prompt)}</b></p><p>你的答案：</p><pre lang="en">${esc(answerLabel(q,run.answers[q.id]))}</pre><p>${ok===null?'參考方向':'正確答案'}：${esc(answerLabel(q,q.answer))}</p><p>${esc(q.why)}</p>${q.rubric?`<p>評閱要點：${esc(q.rubric)}</p>`:''}</article>`;}).join('')}</details>`;}
function paintAnswerProgress(){if(run?.status!=='active'||view!=='room')return;const qs=sectionQuestions(run);for(const [i,q] of qs.entries()){const button=root.querySelector(`[data-act=jump][data-index="${i}"]`),state=answerState(q,run.answers[q.id]);if(button){button.classList.toggle('answered',state==='complete');button.classList.toggle('partial',state==='partial');button.setAttribute('aria-label',`第 ${i+1} 題，${state==='complete'?'完整作答':state==='partial'?'部分作答':'未作答'}`);}}const el=root.querySelector('#answer-progress');if(el)el.textContent=`完整作答 ${qs.filter(q=>answerState(q,run.answers[q.id])==='complete').length}／${qs.length}`;}
function filterReview(){const select=root.querySelector('#review-filter');if(!select)return;select.value=reviewFilter;let count=0;const items=root.querySelectorAll('.review-item');for(const item of items){const d=item.dataset,show=reviewFilter==='all'||reviewFilter==='incorrect'&&d.correct==='false'&&d.manual==='false'||reviewFilter==='incomplete'&&d.incomplete==='true'||reviewFilter==='flagged'&&d.flagged==='true'||reviewFilter==='manual'&&d.manual==='true';item.hidden=!show;if(show)count++;}root.querySelector('#review-count').textContent=`顯示 ${count}／${items.length} 題`;}
let view='home';
function render(){const active=document.activeElement,focus=active?.matches('[data-act=answer]')?active.dataset.value:null;root.innerHTML=view==='home'?home():run?.status==='active'?room():results();if(view!=='home'&&run?.status==='finished')filterReview();if(focus!==null)root.querySelector(`[data-act=answer][data-value="${focus}"]`)?.focus({preventScroll:true});}
function tick(){if(run?.status!=='active')return;if(sync(run)){stopAudio();save();render();}const el=document.querySelector('#clock');if(el){el.textContent=fmt(remaining(run));el.classList.toggle('low',remaining(run)<=300);}if(run.status==='active'&&view==='room'&&profileOf(run.profile).sections[run.section]?.listening)listeningTick();}
// Listening follows a fixed section timeline. Each group gets a slot proportional to
// its spoken words plus answer time. Background/reload never resets a slot.
function currentAudioGroup(){const groups=listeningGroups(run),now=Date.now();return groups.find(g=>now<g.end)||groups.at(-1);}
function listeningTick(){const group=currentAudioGroup(),qs=sectionQuestions(run),current=qs[run.index];if(!group.qs.some(q=>q.id===current.id)){stopAudio();run.index=qs.findIndex(q=>q.id===group.qs[0].id);save();render();if(!run.audio[group.id])playAudio();}const status=document.querySelector('#audio-status');if(status&&!audioBusy)status.textContent=`${run.audio[group.id]==='error'?'音訊中斷，已記錄。':run.audio[group.id]?'本段已播放，不提供重播。':'請播放本段音訊。'} 本題組剩 ${fmt(Math.max(0,Math.ceil((group.end-Date.now())/1000)))}。`;}
function playAudio(){const group=currentAudioGroup();if(run.audio[group.id]||!globalThis.speechSynthesis)return;const q=group.qs[0];run.audio[group.id]='started';save();utterance=new SpeechSynthesisUtterance(q.audio+(q.spokenOptions?' '+q.spokenOptions.map((x,i)=>String.fromCharCode(65+i)+'. '+x).join(' '):''));utterance.lang='en-US';utterance.rate=1;audioBusy=true;playingGroup=group.id;const section=run.section,epoch=++audioEpoch;utterance.onend=()=>{if(epoch!==audioEpoch)return;audioBusy=false;if(run.section!==section||run.status!=='active')return;run.audio[group.id]='complete';save();if(!root.querySelector('dialog[open]'))render();};utterance.onerror=()=>{if(epoch!==audioEpoch)return;audioBusy=false;if(run.section!==section||run.status!=='active')return;run.audio[group.id]='error';save();if(!root.querySelector('dialog[open]'))render();};speechSynthesis.speak(utterance);render();}
root.addEventListener('click',async e=>{const b=e.target.closest('[data-act]');if(!b||b.disabled)return;const a=b.dataset.act,oldSection=run?.section,oldStatus=run?.status;tick();if(oldStatus==='active'&&(oldSection!==run.section||oldStatus!==run.status)&&!['resume','lobby'].includes(a))return;if(a==='recovery-download'){const url=URL.createObjectURL(new Blob([recovery],{type:'application/json'})),link=document.createElement('a');link.href=url;link.download='english-exam-recovery.json';link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);return;}if(a==='prepare')return prepare(b.dataset.id);if(a==='close-dialog')return document.querySelector('#setup').close();if(a==='sound-check'){const status=document.querySelector('#sound-check-status');if(!globalThis.speechSynthesis){status.textContent='本裝置沒有英文語音，請使用支援語音的瀏覽器。';return;}stopAudio();const u=new SpeechSynthesisUtterance('This is an English listening sound check.');u.lang='en-US';u.onend=()=>status.textContent='測試播放完成。';u.onerror=()=>status.textContent='語音播放失敗，請檢查裝置。';speechSynthesis.speak(u);return;}
 if(a==='begin'){const p=profileOf(b.dataset.id);if(p.sections.some(s=>s.listening)&&!globalThis.speechSynthesis){document.querySelector('#sound-check-status').textContent='本裝置無語音，無法啟動聽力模考。';return;}stopAudio();run=createRun(p.id,bank.forms[p.id]);reviewFilter='all';recovery=null;view='room';lastVisit=Date.now();save();render();root.focus({preventScroll:true});window.scrollTo(0,0);return;}
 if(a==='resume'){view='room';tick();render();window.scrollTo(0,0);return;}if(a==='lobby'){markTime();view='home';save();render();return;}
 if(a==='terminate'){const d=document.querySelector('#finish-dialog')||document.querySelector('#setup');d.innerHTML='<h2>提前終止這份模考？</h2><p>會結束計時並保留目前作答、標記未完成。你可以下載報告，再開始其他考試。</p><button class="primary" data-act="confirm-terminate">終止並查看紀錄</button><button data-act="cancel-terminate">繼續模考</button>';d.showModal();return;}if(a==='cancel-terminate'){document.querySelector('dialog[open]').close();return;}if(a==='confirm-terminate'){stopAudio();terminate(run);view='room';save();render();window.scrollTo(0,0);return;}if(a==='download'){const blob=new Blob([JSON.stringify({profile:profileOf(run.profile),report:report(run),run},null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),link=document.createElement('a');link.href=url;link.download=`english-exam-${run.profile}-${new Date(run.startedAt).toISOString().slice(0,10)}.json`;link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);return;}
 if(run?.status!=='active')return;markTime();const qs=sectionQuestions(run),q=qs[run.index],s=profileOf(run.profile).sections[run.section];
 if(a==='answer'){if(s.listening&&!run.audio[q.group])return;const n=Number(b.dataset.value);let val=n;if(q.type==='multi'){val=[...(run.answers[q.id]||[])];if(val.includes(n))val=val.filter(x=>x!==n);else if(!q.selectCount||val.length<q.selectCount)val.push(n);}setAnswer(run,q.id,val);}
 if(a==='flag')run.flags[q.id]=!run.flags[q.id];
 if(a==='jump')navigate(run,Number(b.dataset.index));if(a==='previous')navigate(run,run.index-1);if(a==='next')navigate(run,run.index+1);if(a==='gmat-next')nextGmat(run);
 if(a==='fullscreen'){try{if(document.fullscreenElement)await document.exitFullscreen();else await document.documentElement.requestFullscreen();}catch{}return;}
 if(a==='play')return playAudio();
 if(a==='finish-section'){const unanswered=qs.filter(x=>answerState(x,run.answers[x.id])!=='complete').length,d=document.querySelector('#finish-dialog');d.innerHTML=`<h2>確定結束本節？</h2><p>還有 ${unanswered} 題尚未完整作答（含只填部分空格）。結束後不可返回本節；下一節立刻計時。</p><div class="row"><button class="primary" data-act="confirm-finish">確認交卷</button><button data-act="cancel-finish">繼續作答</button></div>`;d.showModal();return;}
 if(a==='cancel-finish')return document.querySelector('#finish-dialog').close();if(a==='confirm-finish'){stopAudio();advance(run);}
 save();render();if(['jump','previous','next','gmat-next','confirm-finish'].includes(a)){window.scrollTo(0,0);root.querySelector('.question h2')?.focus({preventScroll:true});}
});
root.addEventListener('input',e=>{if(!e.target.dataset.input)return;const qid=e.target.dataset.input;markTime();if(!setAnswer(run,qid,e.target.value)){save();render();return;}save();paintAnswerProgress();const el=document.querySelector('#word-count');if(el)el.textContent=e.target.value.trim().split(/\s+/).filter(Boolean).length+(error?' words · 尚未保存':' words · 已保存');});
root.addEventListener('change',e=>{if(e.target.id==='review-filter'){reviewFilter=e.target.value;filterReview();return;}if(e.target.dataset.blank===undefined)return;const qid=e.target.dataset.q,q=sectionQuestions(run)[run.index],v=[...(run.answers[qid]||q.blanks.map(()=>''))];v[Number(e.target.dataset.blank)]=e.target.value;if(!setAnswer(run,qid,v)){save();render();return;}save();paintAnswerProgress();});
document.addEventListener('visibilitychange',()=>{if(run?.status==='active'){markTime();if(document.hidden)run.hiddenCount++;save();tick();}});
window.addEventListener('beforeunload',()=>{markTime();save();});
window.addEventListener('storage',e=>{if(e.key===STORAGE_KEY){stopAudio();try{const incoming=JSON.parse(e.newValue);const restored=restoreRun(incoming,bank);if(incoming&&!restored){recovery=e.newValue;view='home';run=null;}else{run=restored;if(!run)view='home';}tick();render();}catch{recovery=e.newValue;run=null;view='home';render();}}});
try{const res=await fetch('course/simulation.json?v='+ASSET_VERSION);if(!res.ok)throw Error('HTTP '+res.status);bank=await res.json();try{const raw=localStorage.getItem(STORAGE_KEY);if(raw){try{const saved=JSON.parse(raw);run=restoreRun(saved,bank);if(saved&&!run)recovery=raw;}catch{recovery=raw;}}}catch{error='此瀏覽器無法保存作答。請保持本頁開啟，完成後下載報告。';}if(run?.status==='active'){for(const k in run.audio)if(run.audio[k]==='started')run.audio[k]='error';sync(run);save();}render();setInterval(tick,500);}catch{root.innerHTML='<section class="panel"><h1>試卷載入失敗</h1><p>請檢查網路，然後重新整理。已保存的作答會在試卷載入後接續。</p><button onclick="location.reload()">重新載入</button></section>';}
